from pathlib import Path
import subprocess
import sys
import json

root = Path.cwd()
for name in ('logs_correctos.txt', 'logs_errores.txt', 'logs_correctos2.log', 'logs_errores2.log'):
    current = subprocess.run([sys.executable, '-B', 'analizador.py', name], capture_output=True)
    def normalize(data):
        return data.decode('utf-8-sig').replace('\\r\\n', '\\n')
    now = normalize(current.stdout)
    comparisons = {}
    for period in ('antes', 'despues'):
        historic = root / 'verificacion-semana5' / f'{name}.{period}.stdout.txt'
        historic_err = root / 'verificacion-semana5' / f'{name}.{period}.stderr.txt'
        comparisons[period] = {'stdout_igual': now == normalize(historic.read_bytes()), 'stderr_igual': normalize(current.stderr) == normalize(historic_err.read_bytes())}
    delivery = root / 'verificacion-semana5' / 'entrega' / f'{name}.stdout.txt'
    comparisons['entrega'] = {'stdout_igual': now == normalize(delivery.read_bytes())}
    print(json.dumps({'archivo': name, 'codigo_actual': current.returncode, 'stderr_actual': normalize(current.stderr), 'comparacion': comparisons}, ensure_ascii=True))
