from pathlib import Path
import subprocess
import sys
import json

def read_text(data):
    try:
        return data.decode('utf-8-sig').replace('\\r\\n', '\\n'), 'utf-8-sig'
    except UnicodeDecodeError:
        return data.decode('cp1252').replace('\\r\\n', '\\n'), 'cp1252'

for name in ('logs_correctos.txt', 'logs_errores.txt', 'logs_correctos2.log', 'logs_errores2.log'):
    current = subprocess.run([sys.executable, '-B', 'analizador.py', name], capture_output=True)
    now, current_encoding = read_text(current.stdout)
    comparisons = {}
    for period in ('antes', 'despues'):
        old = (Path('verificacion-semana5') / f'{name}.{period}.stdout.txt').read_bytes()
        old_err = (Path('verificacion-semana5') / f'{name}.{period}.stderr.txt').read_bytes()
        old_text, old_encoding = read_text(old)
        comparisons[period] = {'stdout_bytes_iguales': current.stdout == old, 'stdout_texto_igual': now == old_text, 'codificacion': old_encoding, 'stderr_bytes_iguales': current.stderr == old_err}
    delivery = (Path('verificacion-semana5/entrega') / f'{name}.stdout.txt').read_bytes()
    delivery_text, delivery_encoding = read_text(delivery)
    comparisons['entrega'] = {'stdout_bytes_iguales': current.stdout == delivery, 'stdout_texto_igual': now == delivery_text, 'codificacion': delivery_encoding}
    print(json.dumps({'archivo': name, 'codigo_actual': current.returncode, 'codificacion_actual': current_encoding, 'stderr_actual_vacio': not current.stderr, 'comparacion': comparisons}, ensure_ascii=True))
